import SwiftUI
import Accessibility

/// Accessibility enhancements for dashboard graphics with VoiceOver support
struct AccessibleChartsView: View {
    let chartData: ChartData
    let selectedChartType: ChartType
    
    enum ChartType: String {
        case pie = "Pie Chart"
        case bar = "Bar Chart"
        case line = "Line Chart"
        case area = "Area Chart"
    }
    
    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            // Chart type selector with accessibility
            accessibleChartTypeSelector
            
            // Main chart with accessibility annotations
            chartWithAccessibility
            
            // Data table for screen readers
            accessibilityDataTable
        }
        .padding()
        .background(
            RoundedRectangle(cornerRadius: 20)
                .fill(Color(.secondarySystemBackground))
        )
    }
    
    private var accessibleChartTypeSelector: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("Chart Type")
                .font(.headline)
                .accessibilityAddTraits(.isHeader)
            
            HStack(spacing: 12) {
                ForEach([ChartType.pie, .ChartType.bar, .ChartType.line], id: \\.self) { type in
                    Button(action: {\n                        // Handle chart type selection\n                    }) {\n                        VStack(spacing: 4) {\n                            Image(systemName: type.iconName)\n                                .font(.title2)\n                                .accessibilityHidden(true)\n                            \n                            Text(type.rawValue)\n                                .font(.caption)\n                        }\n                        .padding()\n                        .background(\n                            RoundedRectangle(cornerRadius: 12)\n                                .fill(selectedChartType == type ? .blue : Color(.tertiarySystemBackground))\n                        )\n                        .foregroundColor(selectedChartType == type ? .white : .primary)\n                    }\n                    .accessibilityLabel(\"\\(type.rawValue)\")\n                    .accessibilityHint(selectedChartType == type ? \"Currently selected\" : \"Tap to select\")\n                    .accessibilityAddTraits(selectedChartType == type ? .isSelected : [])\n                }\n            }\n        }\n    }\n    \n    private var chartWithAccessibility: some View {\n        ZStack {\n            // Visual chart\n            visualChart\n                .accessibilityHidden(true)\n            \n            // Accessibility container\n            accessibilityOverlay\n        }\n        .frame(height: 300)\n    }\n    \n    @ViewBuilder\n    private var visualChart: some View {\n        switch selectedChartType {\n        case .pie:\n            AccessiblePieChart(data: chartData.pieData)\n        case .bar:\n            AccessibleBarChart(data: chartData.barData)\n        case .line:\n            AccessibleLineChart(data: chartData.lineData)\n        case .area:\n            AccessibleAreaChart(data: chartData.lineData)\n        }\n    }\n    \n    private var accessibilityOverlay: some View {\n        Group {\n            if selectedChartType == .pie {\n                pieChartAccessibilityDescription\n            } else if selectedChartType == .bar {\n                barChartAccessibilityDescription\n            } else if selectedChartType == .line {\n                lineChartAccessibilityDescription\n            } else {\n                areaChartAccessibilityDescription\n            }\n        }\n        .accessibilityElement(children: .ignore)\n        .accessibilityLabel(chartAccessibilityLabel)\n        .accessibilityHint(chartAccessibilityHint)\n    }\n    \n    private var pieChartAccessibilityDescription: some View {\n        Text(pieChartSummary)\n            .accessibilityElement(children: .ignore)\n            .accessibilityLabel(pieChartSummary)\n    }\n    \n    private var barChartAccessibilityDescription: some View {\n        Text(barChartSummary)\n            .accessibilityElement(children: .ignore)\n            .accessibilityLabel(barChartSummary)\n    }\n    \n    private var lineChartAccessibilityDescription: some View {\n        Text(lineChartSummary)\n            .accessibilityElement(children: .ignore)\n            .accessibilityLabel(lineChartSummary)\n    }\n    \n    private var areaChartAccessibilityDescription: some View {\n        Text(areaChartSummary)\n            .accessibilityElement(children: .ignore)\n            .accessibilityLabel(areaChartSummary)\n    }\n    \n    private var accessibilityDataTable: some View {\n        VStack(alignment: .leading, spacing: 12) {\n            Text(\"Detailed Data\")\n                .font(.headline)\n                .accessibilityAddTraits(.isHeader)\n            \n            switch selectedChartType {\n            case .pie:\n                dataTableForPie\n            case .bar:\n                dataTableForBar\n            case .line:\n                dataTableForLine\n            case .area:\n                dataTableForArea\n            }\n        }\n    }\n    \n    // MARK: - Accessibility Data Tables\n    \n    private var dataTableForPie: some View {\n        VStack(alignment: .leading, spacing: 4) {\n            ForEach(Array(chartData.pieData.enumerated()), id: \\.element.0.id) { index, data in\n                HStack(spacing: 12) {\n                    Circle()\n                        .fill(Color(data.0.name))\n                        .frame(width: 12, height: 12)\n                        .accessibilityHidden(true)\n                    \n                    Text(data.0.name)\n                        .font(.caption)\n                        .accessibilityLabel(\"Category: \\(data.0.name)\")\n                    \n                    Spacer()\n                    \n                    Text(formatCurrency(data.1))\n                        .font(.caption)\n                        .fontWeight(.semibold)\n                        .accessibilityLabel(\"Amount: \\(formatCurrency(data.1))\")\n                }\n                .accessibilityElement(children: .combine)\n                .accessibilityLabel(\"\\(data.0.name): \\(formatCurrency(data.1))\")\n            }\n        }\n        .accessibilityElement(children: .contain)\n        .accessibilityLabel(\"Category breakdown\")\n    }\n    \n    // MARK: - Accessibility Labels\n    \n    private var chartAccessibilityLabel: String {\n        switch selectedChartType {\n        case .pie:\n            return pieChartSummary\n        case .bar:\n            return barChartSummary\n        case .line:\n            return lineChartSummary\n        case .area:\n            return areaChartSummary\n        }\n    }\n    \n    private var chartAccessibilityHint: String {\n        switch selectedChartType {\n        case .pie:\n            return \"Swipe to view detailed category breakdown below\"\n        case .bar:\n            return \"Swipe to view itemized spending amounts below\"\n        case .line:\n            return \"Swipe to view trend data points below\"\n        case .area:\n            return \"Swipe to view area chart data below\"\n        }\n    }\n    \n    private var pieChartSummary: String {\n        let total = chartData.pieData.reduce(0) { $0 + $1.1 }\n        let topCategory = chartData.pieData.max { $0.1 < $1.1 }\n        \n        var summary = \"Pie chart showing spending breakdown across \\(chartData.pieData.count) categories. \"\n        summary += \"Total spending: \\(formatCurrency(total)). \"\n        \n        if let top = topCategory {\n            let percentage = (top.1 / total) * 100\n            summary += \"Highest spending category is \\(top.0.name) at \\(String(format: \"%.0f\", percentage))%.\"\n        }\n        \n        return summary\n    }\n    \n    private var barChartSummary: String {\n        let total = chartData.barData.reduce(0) { $0 + $1.1 }\n        let maxItem = chartData.barData.max { $0.1 < $1.1 }\n        \n        var summary = \"Bar chart showing \\(chartData.barData.count) items. \"\n        summary += \"Total value: \\(formatCurrency(total)). \"\n        \n        if let max = maxItem {\n            summary += \"Highest value: \\(max.0) at \\(formatCurrency(max.1)).\"\n        }\n        \n        return summary\n    }\n    \n    private var lineChartSummary: String {\n        guard !chartData.lineData.isEmpty else {\n            return \"Line chart with no data\"\n        }\n        \n        let values = chartData.lineData\n        let total = values.reduce(0, +)\n        let average = total / Double(values.count)\n        let trend = determineTrend(values)\n        \n        var summary = \"Line chart showing \\(values.count) data points. \"\n        summary += \"Average: \\(formatCurrency(Decimal(average))). \"\n        summary += \"Trend: \\(trend). \"\n        \n        let range = (values.max() ?? 0) - (values.min() ?? 0)\n        summary += \"Range: \\(formatCurrency(Decimal(range))).\"\n        \n        return summary\n    }\n    \n    private var areaChartSummary: String {\n        return lineChartSummary.replacingOccurrences(of: \"Line chart\", with: \"Area chart\")\n    }\n    \n    // MARK: - Helper Methods\n    \n    private func determineTrend(_ values: [Double]) -> String {\n        guard values.count >= 2 else { return \"Insufficient data\" }\n        \n        let firstHalf = values.prefix(values.count / 2)\n        let secondHalf = values.suffix(values.count / 2)\n        \n        let firstAverage = firstHalf.reduce(0, +) / Double(firstHalf.count)\n        let secondAverage = secondHalf.reduce(0, +) / Double(secondHalf.count)\n        \n        let change = ((secondAverage - firstAverage) / firstAverage) * 100\n        \n        if abs(change) < 5 {\n            return \"Stable\"\n        } else if change > 0 {\n            return \"Increasing by \\(String(format: \"%.0f\", abs(change)))%\"\n        } else {\n            return \"Decreasing by \\(String(format: \"%.0f\", abs(change)))%\"\n        }\n    }\n    \n    private func formatCurrency(_ amount: Decimal) -> String {\n        let formatter = NumberFormatter()\n        formatter.numberStyle = .currency\n        formatter.currencyCode = \"INR\"\n        formatter.locale = Locale(identifier: \"en_IN\")\n        formatter.maximumFractionDigits = 0\n        return formatter.string(from: NSDecimalNumber(decimal: amount)) ?? \"₹0\"\n    }\n}\n\n// MARK: - Specialized Accessible Chart Components\n\nstruct AccessiblePieChart: View {\n    let data: [(Category, Double)]\n    \n    var body: some View {\n        Chart {\n            ForEach(Array(data.enumerated()), id: \\.element.0.id) { index, categoryData in\n                SectorMark(\n                    angle: .value(\"Amount\", categoryData.1),\n                    innerRadius: .ratio(0.4),\n                    angularInset: 2.0\n                )\n                .foregroundStyle(.byValue(\"Category\", categoryData.0.name))\n                .accessibilityElement(children: .ignore)\n            }\n        }\n        .chartLegend(position: .bottom)\n        .accessibilityElement(children: .ignore)\n    }\n}\n\nstruct AccessibleBarChart: View {\n    let data: [(String, Double)]\n    \n    var body: some View {\n        Chart {\n            ForEach(Array(data.enumerated()), id: \\.offset) { index, item in\n                BarMark(\n                    x: .value(\"Category\", item.0),\n                    y: .value(\"Amount\", item.1)\n                )\n                .foregroundStyle(.blue)\n                .cornerRadius(4)\n                .accessibilityElement(children: .ignore)\n            }\n        }\n        .accessibilityElement(children: .ignore)\n    }\n}\n\nstruct AccessibleLineChart: View {\n    let data: [Double]\n    \n    var body: some View {\n        Chart {\n            ForEach(Array(data.enumerated()), id: \\.offset) { index, value in\n                LineMark(\n                    x: .value(\"Point\", index),\n                    y: .value(\"Value\", value)\n                )\n                .foregroundStyle(.blue)\n                .lineStyle(StrokeStyle(lineWidth: 3))\n                .symbol {\n                    Circle()\n                        .fill(.blue)\n                        .frame(width: 8, height: 8)\n                }\n                .accessibilityElement(children: .ignore)\n            }\n        }\n        .accessibilityElement(children: .ignore)\n    }\n}\n\nstruct AccessibleAreaChart: View {\n    let data: [Double]\n    \n    var body: some View {\n        Chart {\n            ForEach(Array(data.enumerated()), id: \\.offset) { index, value in\n                AreaMark(\n                    x: .value(\"Point\", index),\n                    y: .value(\"Value\", value)\n                )\n                .foregroundStyle(\n                    LinearGradient(\n                        gradient: Gradient(colors: [.blue.opacity(0.6), .blue.opacity(0.1)]),\n                        startPoint: .top,\n                        endPoint: .bottom\n                    )\n                )\n                .accessibilityElement(children: .ignore)\n            }\n        }\n        .accessibilityElement(children: .ignore)\n    }\n}\n\n// MARK: - Data Models for Accessibility\n\nstruct ChartData {\n    let pieData: [(Category, Double)]\n    let barData: [(String, Double)]\n    let lineData: [Double]\n}\n\n// MARK: - Extensions for Accessibility\n\nextension ChartType {\n    var iconName: String {\n        switch self {\n        case .pie: return \"chart.pie.fill\"\n        case .bar: return \"chart.bar.fill\"\n        case .line: return \"chart.line.uptrend.xyaxis\"\n        case .area: return \"chart.area\"\n        }\n    }\n}\n\n// MARK: - Enhanced Dashboard with Accessibility\n\nstruct EnhancedDashboardView: View {\n    @ObservedObject var viewModel: DashboardViewModel\n    @State private var accessibilityModeEnabled = UIAccessibility.isVoiceOverRunning\n    \n    var body: some View {\n        ScrollView {\n            LazyVStack(spacing: 20) {\n                // Header with accessibility\n                accessibleHeaderSection\n                \n                // Main content\n                if accessibilityModeEnabled {\n                    accessibilityOptimizedContent\n                } else {\n                    regularVisualContent\n                }\n            }\n            .padding()\n        }\n        .onReceive(NotificationCenter.default.publisher(for: UIAccessibility.voiceOverStatusDidChangeNotification)) { _ in\n            accessibilityModeEnabled = UIAccessibility.isVoiceOverRunning\n        }\n        .accessibilityElement(children: .contain)\n        .accessibilityLabel(\"Expense tracker dashboard\")\n        .accessibilityHint(\"Swipe to navigate through different sections\")\n    }\n    \n    private var accessibleHeaderSection: some View {\n        VStack(alignment: .leading, spacing: 16) {\n            Text(\"Expense Tracker Dashboard\")\n                .font(.largeTitle)\n                .fontWeight(.bold)\n                .accessibilityAddTraits(.isHeader)\n            \n            if let dashboard = viewModel.dashboardData {\n                VStack(alignment: .leading, spacing: 8) {\n                    Text(\"Total Spending\")\n                        .font(.subheadline)\n                        .foregroundColor(.secondary)\n                    \n                    Text(viewModel.formatCurrency(dashboard.totalSpending))\n                        .font(.title)\n                        .fontWeight(.bold)\n                        .accessibilityLabel(\"Total spending: \\(viewModel.formatCurrency(dashboard.totalSpending))\")\n                    \n                    Text(\"\\(dashboard.totalTransactions) transactions\")\n                        .font(.caption)\n                        .foregroundColor(.secondary)\n                        .accessibilityLabel(\"\\(dashboard.totalTransactions) transactions in selected period\")\n                }\n            }\n        }\n        .accessibilityElement(children: .combine)\n        .accessibilityLabel(\"Dashboard header with total spending and transaction count\")\n    }\n    \n    @ViewBuilder\n    private var accessibilityOptimizedContent: some View {\n        // Simplified content for VoiceOver users\n        VStack(spacing: 20) {\n            // Spending summary\n            if let dashboard = viewModel.dashboardData {\n                accessibleSpendingSummary(dashboard)\n            }\n            \n            // Category breakdown\n            if let dashboard = viewModel.dashboardData {\n                accessibleCategoryBreakdown(dashboard.categoryBreakdown)\n            }\n            \n            // Budget status\n            if let dashboard = viewModel.dashboardData {\n                accessibleBudgetStatus(dashboard.budgetStatuses)\n            }\n        }\n    }\n    \n    @ViewBuilder\n    private var regularVisualContent: some View {\n        // Full visual content for sighted users\n        // Import the enhanced visual components created earlier\n        Text(\"Visual Dashboard Content\")\n            .placeholder()\n    }\n    \n    // MARK: - Accessibility Helper Views\n    \n    private func accessibleSpendingSummary(_ dashboard: DashboardData) -> some View {\n        VStack(alignment: .leading, spacing: 12) {\n            Text(\"Spending Summary\")\n                .font(.headline)\n                .accessibilityAddTraits(.isHeader)\n            \n            VStack(alignment: .leading, spacing: 8) {\n                HStack {\n                    Text(\"Total:\")\n                        .foregroundColor(.secondary)\n                    Text(viewModel.formatCurrency(dashboard.totalSpending))\n                        .fontWeight(.semibold)\n                }\n                .accessibilityElement(children: .combine)\n                .accessibilityLabel(\"Total spending: \\(viewModel.formatCurrency(dashboard.totalSpending))\")\n                \n                HStack {\n                    Text(\"Transactions:\")\n                        .foregroundColor(.secondary)\n                    Text(\"\\(dashboard.totalTransactions)\")\n                        .fontWeight(.semibold)\n                }\n                .accessibilityElement(children: .combine)\n                .accessibilityLabel(\"\\(dashboard.totalTransactions) transactions\")\n            }\n        }\n        .padding()\n        .background(Color(.tertiarySystemBackground))\n        .cornerRadius(12)\n        .accessibilityElement(children: .contain)\n    }\n    \n    private func accessibleCategoryBreakdown(_ categoryData: [(Category, Decimal)]) -> some View {\n        VStack(alignment: .leading, spacing: 12) {\n            Text(\"Category Breakdown\")\n                .font(.headline)\n                .accessibilityAddTraits(.isHeader)\n            \n            ForEach(Array(categoryData.enumerated()), id: \\.element.0.id) { index, categoryData in\n                let percentage = dashboardData?.getCategorySpendingPercentage(for: categoryData.0) ?? 0\n                \n                HStack {\n                    Text(categoryData.0.name)\n                        .fontWeight(.medium)\n                    Spacer()\n                    Text(viewModel.formatCurrency(categoryData.1))\n                        .fontWeight(.semibold)\n                    Text(\"(\\(String(format: \"%.0f\", percentage * 100))%)\")\n                        .foregroundColor(.secondary)\n                }\n                .accessibilityElement(children: .combine)\n                .accessibilityLabel(\"\\(categoryData.0.name): \\(viewModel.formatCurrency(categoryData.1)), \\(String(format: \"%.0f\", percentage * 100))% of total\")\n            }\n        }\n        .padding()\n        .background(Color(.tertiarySystemBackground))\n        .cornerRadius(12)\n        .accessibilityElement(children: .contain)\n    }\n    \n    private func accessibleBudgetStatus(_ budgetData: [(Category, BudgetStatus)]) -> some View {\n        VStack(alignment: .leading, spacing: 12) {\n            Text(\"Budget Status\")\n                .font(.headline)\n                .accessibilityAddTraits(.isHeader)\n            \n            ForEach(budgetData, id: \\.0.id) { category, status in\n                HStack {\n                    Text(category.name)\n                        .fontWeight(.medium)\n                    Spacer()\n                    Text(status.message)\n                        .foregroundColor(statusColor(for: status))\n                }\n                .accessibilityElement(children: .combine)\n                .accessibilityLabel(\"\\(category.name) budget status: \\(status.message)\")\n            }\n        }\n        .padding()\n        .background(Color(.tertiarySystemBackground))\n        .cornerRadius(12)\n        .accessibilityElement(children: .contain)\n    }\n    \n    private func statusColor(for status: BudgetStatus) -> Color {\n        switch status {\n        case .withinLimit: return .green\n        case .approachingLimit: return .orange\n        case .exceededLimit: return .red\n        }\n    }\n}\n\n#Preview {\n    ScrollView {\n        AccessibleChartsView(\n            chartData: ChartData(\n                pieData: [\n                    (Category(id: UUID(), name: \"Food\", isDefault: true), 3000),\n                    (Category(id: UUID(), name: \"Transport\", isDefault: true), 2000)\n                ],\n                barData: [\n                    (\"Food\", 3000),\n                    (\"Transport\", 2000)\n                ],\n                lineData: [1000, 1500, 1200, 1800]\n            ),\n            selectedChartType: .pie\n        )\n    }\n    .padding()\n}